Method.Implementation:
	set tSC = $$$OK
	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.OrderSuperset).%New()

	set dbObj = ##class(IHC.ITF.ITFCOMMON.Operation.CallTouchWorksStoredProcedures).%New(..Adapter)

	Set tSC = dbObj.GetExtractEncounterCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractEncounterCMS CMSEvent_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
  	set pResponse.ExtractEncounterCMS = resp
  	Set tSC = dbObj.GetExtractPatientCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractPatientCMS Event_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
	set pResponse.ExtractPatientCMS = resp

  	Set tSC = dbObj.GetExtractPersonCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractPersonCMS Event_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
	set pResponse.ExtractPersonCMS = resp

  	Set tSC = dbObj.GetExtractOrderItemCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractOrderItemCMS Event_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
	set pResponse.ExtractOrderItemCMS = resp

  	Set tSC = dbObj.GetExtractInsuranceCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractInsuranceCMS Event_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
	set pResponse.ExtractInsurance = resp

  	Set tSC = dbObj.GetExtractCase(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractCase Event_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
	set pResponse.ExtractCase = resp

  	Set tSC = dbObj.GetExtractOrderAdditionalInformationString(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return $system.Status.AppendStatus(tSC, $$$ERROR($$$DatabaseError, ", GetExtractOrderAdditionalInformationString Event_Table: EventSequenceID" _ req.EventSequenceID _", PersonID" _ req.PersonID _ ", OrderID" _ req.OrderID))
  	}
	set pResponse.ExtractOrderAdditionalInformationString = resp

  	return tSC
